def _lex(s):
    out=[]; pos=0
    while pos < len(s):
        m=_TOKEN.match(s,pos)
        if not m: raise QueryError("syntax error")
        raw=m.group(); pos=m.end()
        if raw.isspace() or raw.startswith('--') or raw.startswith('/*'): continue
        if raw.startswith("'"): out.append(Tok('lit',raw[1:-1].replace("''", "'"),raw))
        elif raw.startswith('"'): out.append(Tok('id',raw[1:-1].replace('""','"'),raw))
        elif raw[0].isdigit() or raw[0]=='.': out.append(Tok('lit',float(raw) if '.' in raw else int(raw),raw))
        elif raw[0].isalpha() or raw[0]=='_':
            u=raw.upper()
            if u in ('NULL','TRUE','FALSE'): out.append(Tok('lit', {'NULL':None,'TRUE':True,'FALSE':False}[u],raw))
            else: out.append(Tok('kw' if u in _KEYWORDS else 'id',u if u in _KEYWORDS else raw,raw))
        else: out.append(Tok('op',raw,raw))
    out.append(Tok('eof',None,'')); return out


